57	union alignas(64) thread_rng {
58	    uint8_t u8[64];
59	    uint32_t u32[sizeof(u8) / sizeof(uint32_t)];
60	    uint64_t u64[sizeof(u8) / sizeof(uint64_t)];
61	    __uint128_t u128[sizeof(u8) / sizeof(__uint128_t)];
62	#ifdef __x86_64__
63	    __m128i m128[sizeof(u8) / sizeof(__m128i)];
64	#elif defined(__aarch64__)
65	    uint8x16_t m128[sizeof(u8) / sizeof(uint8x16_t)];
66	#endif
67	};
