89	struct RandomEngineWrapper
90	{
91	    std::vector<thread_rng> per_thread;
92	    EngineType engine_type;
93	
94	    RandomEngineWrapper(EngineType type)
95	        : per_thread(thread_count() + 1), engine_type(type)
96	    {}
97	
98	    virtual ~RandomEngineWrapper();
99	    virtual size_t stateSize() = 0;
100	    virtual std::string globalState() = 0;
101	    virtual void reloadGlobalState(const char *argument) = 0;
102	    virtual void seedGlobalEngine(SeedSequence &sseq) = 0;
103	    virtual void seedThread(thread_rng *thread_buffer, uint32_t mixin) = 0;
104	    virtual uint32_t generate32(thread_rng *thread_buffer) = 0;
105	    virtual uint64_t generate48(thread_rng *thread_buffer) = 0;
106	    virtual uint64_t generate64(thread_rng *thread_buffer) = 0;
107	    virtual long int generateInt(thread_rng *thread_buffer) = 0;
108	    virtual __uint128_t generate128(thread_rng *thread_buffer) = 0;
109	};
110	RandomEngineWrapper::~RandomEngineWrapper() {}
