118	static thread_rng *rng_for_thread(int thread_num)
119	{
120	    assert(thread_num < thread_count());
121	    assert(thread_num >= -1);
122	
123	    auto &rngs = sApp->random_engine->per_thread;
124	    assert(rngs.size());
125	    return &rngs[thread_num + 1];
126	}
