133	template <typename E> struct EngineWrapper : public RandomEngineWrapper
134	{
135	    using engine_type = E;
136	
137	    EngineWrapper(EngineType type) : RandomEngineWrapper(type)
138	    {
139	        static_assert(sizeof(engine_type) <= sizeof(thread_rng), "engine is too big");
140	        static_assert(std::is_trivially_copyable_v<engine_type>,
141	                "engine is not trivially copyable on this platform");
142	        static_assert(std::is_trivially_destructible_v<engine_type>,
143	                "engine is not trivially destructible on this platform");
144	        staticAssertions();
145	    }
146	    void staticAssertions() {}      // specialiseable
147	
148	    size_t stateSize() override
149	    {
150	        return sizeof(engine_type);
151	    }
152	
153	    std::string globalState() override
154	    {
155	        std::ostringstream ss;
156	        ss << globalEngine();
157	        return ss.str();
158	    }
159	
160	    void reloadGlobalState(const char *argument) override
161	    {
162	        std::istringstream ss(argument);
163	        ss >> globalEngine();
164	    }
165	
166	    void seedGlobalEngine(SeedSequence &sseq) override
167	    {
168	        new (rng_for_thread(-1)->u8) engine_type(*sseq.data());
169	    }
170	
171	    void seedThread(thread_rng *buffer, uint32_t mixin) override
172	    {
173	        // generic version: just XOR the mixin to the global engine's current state
174	        thread_rng *global = rng_for_thread(-1);
175	        for (size_t i = 0; i < std::size(buffer->u32); ++i)
176	            buffer->u32[i] = global->u32[i] ^ mixin;
177	    }
178	
179	    uint32_t generate32(thread_rng *buffer) override
180	    {
181	        return uint32_t(engine(buffer)());
182	    }
183	
184	    uint64_t generate48(thread_rng *thread_buffer) override
185	    {
186	        return generate64(thread_buffer) & ((UINT64_C(1) << 48) - 1U);
187	    }
188	
189	    uint64_t generate64(thread_rng *thread_buffer) override
190	    {
191	        return generate32(thread_buffer) | (uint64_t(generate32(thread_buffer)) << 32);
192	    }
193	
194	    long int generateInt(thread_rng *thread_buffer) override
195	    {
196	        return generate32(thread_buffer) & 0x7fffffff;
197	    }
198	
199	    __uint128_t generate128(thread_rng *thread_buffer) override
200	    {
201	        return generate64(thread_buffer) | (__uint128_t(generate64(thread_buffer)) << 64);
202	    }
203	
204	protected:
205	    static E &engine(thread_rng *generator)
206	    {
207	        return *reinterpret_cast<E *>(generator->u8);
208	    }
209	
210	    static E &globalEngine()
211	    {
212	        return engine(rng_for_thread(-1));
213	    }
214	};
