217	// NOT random!!
218	
219	struct constant_value_engine
220	{
221	    using result_type = uint32_t;
222	    result_type value;
223	    constant_value_engine(result_type v) : value(v) {}
224	    result_type operator()() { return value;}
225	    constexpr static result_type min() { return 0; }
226	    constexpr static result_type max() { return std::numeric_limits<result_type>::max(); }
227	
228	    friend std::ostringstream &operator<<(std::ostringstream &ss, constant_value_engine x)
229	    {
230	        ss.flags(std::ios_base::showbase);
231	        if (x.value > 255)
232	            ss << std::hex;
233	        ss << x.value;
234	        return ss;
235	    }
236	
237	    friend std::istringstream &operator>>(std::istringstream &ss, constant_value_engine &x)
238	    {
239	        ss.flags(std::ios_base::showbase);
240	        ss >> x.value;
241	        return ss;
242	    }
243	};
244	template struct EngineWrapper<constant_value_engine>;
