246	// -- linear congruential engine (minimum standard) --
247	
248	template <> void EngineWrapper<std::minstd_rand>::staticAssertions()
249	{
250	    static_assert(engine_type::min() == 1, "invalid internal assumption");
251	    static_assert(engine_type::max() == 0x7ffffffe, "invalid internal assumption");
252	}
