254	template <>
255	void EngineWrapper<std::minstd_rand>::seedThread(thread_rng *generator, uint32_t mixin)
256	{
257	    mixin &= engine_type::max();
258	    std::minstd_rand global = globalEngine();   // copies, so we don't modify the global
259	    new (&engine(generator)) std::minstd_rand(global() ^ mixin);
260	}
