262	template <>
263	uint32_t EngineWrapper<std::minstd_rand>::generate32(thread_rng *generator)
264	{
265	    // need two samples to make 32 bits
266	    return (engine(generator)() & 0xffff) |
267	            ((engine(generator)() & 0xffff) << 16);
268	}
269	
270	template <>
271	uint64_t EngineWrapper<std::minstd_rand>::generate48(thread_rng *generator)
272	{
273	    // need two samples to make 48 bits
274	    return (engine(generator)() & 0xffffff) |
275	            (uint64_t(engine(generator)() & 0xffffff) << 24);
276	}
277	
278	template <>
279	uint64_t EngineWrapper<std::minstd_rand>::generate64(thread_rng *generator)
280	{
281	    // need three samples to make 64 bits
282	    return generate48(generator) |
283	            (uint64_t(engine(generator)() & 0xffffff) << 48);
284	}
