295	#ifdef RANDOM_HAS_AES
296	// -- AES engine (generates numbers by running AES over a state) --
297	static bool haveAes()
298	{
299	#if !defined(__x86_64__)
300	    // Non-x86: rely on the framework's feature detection (HWCAP on AArch64).
301	    return device_has_feature(cpu_feature_aes);
302	#else
303	    uint32_t eax, ebx, ecx, edx;
304	    __cpuid(1, eax, ebx, ecx, edx);
305	    return bit_AES & ecx;
306	#endif
307	}
