309	#ifdef __x86_64__
310	#pragma GCC push_options
311	#pragma GCC target("aes")
312	struct aes_engine
313	{
314	    __m128i state[2];
315	    aes_engine(const uint32_t &sseq)
316	    {
317	        __m128i pattern = _mm_loadu_si128(reinterpret_cast<const __m128i *>(&sseq));
318	        _mm_store_si128(state + 0, pattern);
319	        pattern = _mm_xor_si128(pattern, _mm_set1_epi32(-1));
320	        _mm_store_si128(state + 1, pattern);
321	    }
322	
323	    __m128i generateM128()
324	    {
325	        __m128i v1 = _mm_aesenc_si128(state[0], state[1]);
326	        _mm_store_si128(state + 0, v1);
327	        return v1;
328	    }
329	};
330	
331	template<>
332	std::string EngineWrapper<aes_engine>::globalState()
333	{
334	    static const char hexdigits[] = "0123456789abcdef";
335	    const uint8_t *state = rng_for_thread(-1)->u8;
336	    std::string result;
337	    result.resize(2 * sizeof(aes_engine::state));
338	    for (size_t i = 0; i < sizeof(aes_engine::state); ++i) {
339	        result[2 * i + 0] = hexdigits[state[i] >> 4];
340	        result[2 * i + 1] = hexdigits[state[i] & 0xf];
341	    }
342	    return result;
343	}
344	
345	template<>
346	void EngineWrapper<aes_engine>::reloadGlobalState(const char *ptr)
347	{
348	    uint8_t *state = rng_for_thread(-1)->u8;
349	    for (size_t i = 0; ptr[i]; ++i) {
350	        unsigned char c = ptr[i];
351	        // dirty, doesn't check if it's out of range!
352	        unsigned char nibble = c >= 'a' ? c - 'a' + 10 :
353	                                          c >= 'A' ? c - 'A' + 10 : c - '0';
354	
355	        auto b = state + i / 2;
356	        if (i % 2 == 0)
357	            *b = nibble << 4;
358	        else
359	            *b |= nibble;
360	    }
361	}
