375	template<>
376	__uint128_t EngineWrapper<aes_engine>::generate128(thread_rng *generator)
377	{
378	    __m128i r = engine(generator).generateM128();
379	    uint64_t l = _mm_extract_epi64(r, 0);
380	    uint64_t h = _mm_extract_epi64(r, 1);
381	    return l | (__uint128_t(h) << 64);
382	}
383	#pragma GCC pop_options
384	
385	#elif defined(__aarch64__)
386	/*
387	 * ARM equivalent of the x86 aes_engine. Uses the AArch64 NEON AES
388	 * instructions (AESE + AESMC) instead of the Intel AESENC intrinsic.
389	 * vaesmcq_u8(vaeseq_u8(data, key)) is the ARM counterpart to
390	 * _mm_aesenc_si128(data, key) (one AES round: SubBytes/ShiftRows/
391	 * AddRoundKey followed by MixColumns).
392	 *
393	 * The +crypto target attribute enables the AES instructions for just
394	 * this engine on a generic AArch64 build (mirroring x86's
395	 * #pragma GCC target("aes")).
396	 */
397	#pragma GCC push_options
398	#pragma GCC target("+crypto")
399	struct aes_engine
400	{
401	    uint8x16_t state[2];
402	    aes_engine(const uint32_t &sseq)
403	    {
404	        uint8x16_t pattern = vld1q_u8(reinterpret_cast<const uint8_t *>(&sseq));
405	        state[0] = pattern;
406	        state[1] = veorq_u8(pattern, vdupq_n_u8(0xff));
407	    }
408	
409	    uint8x16_t generateM128()
410	    {
411	        // AESE (SubBytes/ShiftRows/AddRoundKey) + AESMC (MixColumns)
412	        uint8x16_t v = vaesmcq_u8(vaeseq_u8(state[0], state[1]));
413	        state[0] = v;
414	        return v;
415	    }
416	};
417	#pragma GCC pop_options
