486	static const char *engineNameFromType(EngineType t)
487	{
488	    switch (t) {
489	    case Constant:
490	        return "Constant";
491	    case LCG:
492	        return "LCG";
493	    case AESSequence:
494	        return "AES";
495	    }
496	    __builtin_unreachable();
497	    return nullptr;
