500	static void listEngines(FILE *stream)
501	{
502	    for (EngineType t : engine_types)
503	        fprintf(stream, "  %s\n", engineNameFromType(t));
504	}
505	
506	static EngineType engineFromName(std::string_view argument)
507	{
508	    for (EngineType type : engine_types) {
509	        std::string_view name = engineNameFromType(type);
510	        if (!argument.starts_with(name))
511	            continue;
512	        if (argument.size() != name.size() && argument[name.size()] != ':')
513	            continue;
514	
515	        if (type == AESSequence && !haveAes()) {
516	            fprintf(stderr, "%s: engine type '%s' not available on this system. Available engines are:\n",
517	                    program_invocation_name, name.data());
518	            listEngines(stderr);
519	            exit(EX_USAGE);
520	        }
521	        return type;
522	    }
523	    fprintf(stderr, "%s: invalid random engine seed '%s'. Available engines are:\n",
524	            program_invocation_name, argument.data());
525	    listEngines(stderr);
526	    exit(EX_USAGE);
527	}
