529	static inline int open_random_file(const char *filename)
530	{
531	    if (SandstoneConfig::RestrictedCommandLine || !filename) {
532	#ifdef _WIN32
533	        return -1;          // fall back to RtlGenRandom
534	#endif
535	        filename = "/dev/urandom";
536	    }
537	    return open(filename, O_RDONLY | O_CLOEXEC);
538	}
539	
540	static int read_random_file(int fd, void *where, size_t count)
541	{
542	    if (fd >= 0)
543	        return read(fd, where, count);
544	
545	    // no file
546	    constexpr size_t RandomDataSize = 16;
547	
548	#ifdef AT_RANDOM
549	    // On Linux, AT_RANDOM was added on kernel 2.6.29, so we rely on it always
550	    // being present. We'll crash if it is not, but I guess you deserve it.
551	    // AT_RANDOM provides us with 128 bits of random data, which is sufficient to
552	    // either the LCG or AES generators.
553	    unsigned long randomdata = getauxval(AT_RANDOM);
554	    auto randomdataptr = reinterpret_cast<const void *>(randomdata);
555	#elif defined(_WIN32)
556	    // On Windows, /dev/urandom won't exist, so let's use RtlGenRandom to
557	    // generate 128 bits of random data.
558	    auto RtlGenRandom = SystemFunction036;
559	    uint32_t randomdataptr[RandomDataSize / sizeof(uint32_t)];
560	    if (!RtlGenRandom(randomdataptr, sizeof(randomdataptr))) {
561	        // RtlGenRandom failed, fall back to rand_s
562	        for (unsigned &u : randomdataptr)
563	            IGNORE_RETVAL(rand_s(&u));
564	    }
565	#else
566	    return 0;
567	#endif
568	    count = std::min(RandomDataSize, count);
569	    memcpy(where, randomdataptr, count);
570	    return count;
571	}
