573	void random_init_global(const char *seed_from_user)
574	{
575	    assert(thread_count() > 0);
576	    assert(thread_num == -1);
577	
578	    if (seed_from_user && (strcmp(seed_from_user, "help") == 0 || strcmp(seed_from_user, "list") == 0)) {
579	        listEngines(stdout);
580	        exit(0);
581	    }
582	
583	    // treat the argument as if it were a file, see if it works
584	    auto_fd fd = { open_random_file(seed_from_user) };
585	    auto read_from_seed = [&](auto &where) {
586	        int n = read_random_file(fd, &where, sizeof(where));
587	        if (n != sizeof(where)) [[unlikely]] {
588	            if (seed_from_user)
589	                fprintf(stderr, "%s: could not read from %s: %s\n", program_invocation_name,
590	                        seed_from_user, n < 0 ? strerror(errno) : "File too short");
591	            exit(EX_IOERR);
592	        }
593	        return true;
594	    };
595	
596	    EngineType engine_type;
597	    if (fd == -1 && seed_from_user) {
598	        // not a file (or does not exist), attempt to parse
599	        engine_type = engineFromName(seed_from_user);
600	        seed_from_user = strchr(seed_from_user, ':');
601	        if (seed_from_user)
602	            ++seed_from_user;           // skip the ':'
603	    } else {
604	        // no engine provided, choose one randomly
605	        uint8_t type;
606	        seed_from_user = nullptr;
607	        engine_type = LCG;
608	        if (haveAes() && read_from_seed(type) && (type & 2))
609	            engine_type = AESSequence;
610	    }
611	
612	    switch (engine_type) {
613	    case Constant:
614	        sApp->random_engine.reset(new EngineWrapper<constant_value_engine>(engine_type));
615	        break;
616	    case AESSequence:
617	#ifdef RANDOM_HAS_AES
618	        sApp->random_engine.reset(new EngineWrapper<aes_engine>(engine_type));
619	#else
620	        assert("Impossible condition: shouldn't have reached here");
621	        __builtin_unreachable();
622	#endif
623	        break;
624	    case LCG:
625	        sApp->random_engine.reset(new EngineWrapper<std::minstd_rand>(engine_type));
626	        break;
627	    }
628	
629	    if (seed_from_user && *seed_from_user) {
630	        // use the seed state provided in the command-line
631	        sApp->random_engine->reloadGlobalState(seed_from_user);
632	    } else {
633	        // use a random-generated seed
634	        SeedSequence sseq;
635	        read_from_seed(sseq);
636	        sApp->random_engine->seedGlobalEngine(sseq);
637	    }
638	}
