713	void *memset_random(void *buf, size_t n)
714	{
715	    if (n <= sizeof(uint64_t)) {
716	        if (n > sizeof(uint32_t)) {
717	            uint64_t v = random64();
718	            return memcpy(buf, &v, n);
719	        }
