726	    if (n < sizeof(v))
727	        return memcpy(buf, &v, n);
728	
729	    uint8_t *ptr = static_cast<uint8_t *>(buf);
730	    uint8_t *end = ptr + n;
731	    while (end - ptr > sizeof(v)) {
732	        memcpy(ptr, &v, sizeof(v));
733	        v = random128();
734	        ptr += sizeof(v);
735	    }
736	
737	    if (end - ptr)
