743	uint64_t set_random_bits(unsigned num_bits_to_set, uint32_t bitwidth) {
744	    if (num_bits_to_set >= 64 && bitwidth >= 64)
745	        return 0xFFFFFFFFFFFFFFFF;  // can't be handled by shifting and subtracting :-(
746	    else if (num_bits_to_set >= bitwidth || num_bits_to_set >= 64)
747	        return (1ul << bitwidth) - 1ul;
748	
749	    // Create a list of all possible bits we could set (basically 1 .. bitwidth)
750	    uint32_t bit_positions[64];
751	    for(unsigned i=0; i < bitwidth; i++) {
752	        bit_positions[i] = i;
753	    }
754	
755	
756	    uint64_t value = 0;
757	    uint32_t num_unset_bits = bitwidth;
758	    while (num_bits_to_set > 0) {
759	
760	        // pick a bit position from the bit_positions array for what
761	        // we have left in the list to select as indicated by num_unset_bits
762	        int idx_of_bit_to_set = random32() % num_unset_bits;
763	        uint32_t bitpos_to_set = bit_positions[idx_of_bit_to_set];
764	
765	        // set the bit
766	        value |= UINT64_C(1) << bitpos_to_set; // set the bit
767	
768	        // remove the selected bit from the list and shorten the list by 1
769	        // If we remove the last entry, shortening the list is removing it
770	        // otherwise we swap the last entry in bit_positions with the one
771	        // we just selected, the shorten the list
772	        if (idx_of_bit_to_set < num_unset_bits - 1)
773	            bit_positions[idx_of_bit_to_set] = bit_positions[num_unset_bits - 1];
774	
775	        num_unset_bits -= 1;  // shortens the list by 1
776	        num_bits_to_set--;    // loop count
777	    }
778	    return value;
779	}
