#  include <sys/auxv.h>
#endif

#ifdef _WIN32
#  define WIN32_LEAN_AND_MEAN
#  include <windows.h>

// MS docs at https://msdn.microsoft.com/en-us/library/windows/desktop/aa387694(v=vs.85).aspx say:
