1	/**
2	 * @copyright
3	 * Copyright 2022 Intel Corporation.
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * @test @b ipsec_aes128_cbc_hmac_sha1_avx
7	 * @parblock
8	 * This test encrypts random data using AES-128-CBC encryption and computes
9	 * an HMAC-SHA1-96 message authentication code (truncated to 12 bytes) on the
10	 * ciphertext via OpenSSL using the AVX optimized code path. It also decrypts 
11	 * the ciphertext and verifies that it matches the original plaintext. The 
12	 * ciphertext, MAC, and decrypted data are compared against pre-computed 
13	 * golden values on every iteration to detect silent data corruption.
14	 * @endparblock
15	 */
16	
17	#include "sandstone.h"
18	
19	#if SANDSTONE_SSL_BUILD
20	#include "sandstone_ssl.h"
21	#include <string.h>
22	
23	#define DATA_SIZE             (1024u)
24	#define AES_KEY_SIZE          (16)
25	#define AES_IV_SIZE           (16)
26	#define SHA1_KEY_SIZE         (20)
27	#define SHA1_96_DIGEST_SIZE   (12)
28	#define SHA1_FULL_DIGEST_SIZE (20)
29	
30	struct hmac_sha1_avx_data {
31	    uint8_t aes_key[AES_KEY_SIZE];
32	    uint8_t aes_iv[AES_IV_SIZE];
33	    uint8_t hmac_key[SHA1_KEY_SIZE];
34	    uint8_t plaintext[DATA_SIZE];
35	    uint8_t golden_ciphertext[DATA_SIZE];
36	    uint8_t golden_mac[SHA1_96_DIGEST_SIZE];
37	};
38	
39	static void hmac_sha1_96(const uint8_t *key, const uint8_t *msg, size_t len, uint8_t *out) {
40	    HMAC_CTX *ctx = s_HMAC_CTX_new();
41	    s_HMAC_Init_ex(ctx, key, SHA1_KEY_SIZE, s_EVP_sha1(), NULL);
42	    s_HMAC_Update(ctx, msg, len);
43	    uint8_t full_mac[SHA1_FULL_DIGEST_SIZE];
44	    unsigned int outlen;
45	    s_HMAC_Final(ctx, full_mac, &outlen);
46	    s_HMAC_CTX_free(ctx);
47	    memcpy(out, full_mac, SHA1_96_DIGEST_SIZE);
48	}
49	
50	static void aes_encrypt(const uint8_t *key, const uint8_t *iv, const uint8_t *in, uint8_t *out, size_t len) {
51	    EVP_CIPHER_CTX *ctx = s_EVP_CIPHER_CTX_new();
52	    s_EVP_EncryptInit_ex(ctx, s_EVP_aes_128_cbc(), NULL, key, iv);
53	    s_EVP_CIPHER_CTX_set_padding(ctx, 0);
54	    int outlen;
55	    s_EVP_EncryptUpdate(ctx, out, &outlen, in, len);
56	    int outlen2;
57	    s_EVP_EncryptFinal_ex(ctx, out + outlen, &outlen2);
58	    s_EVP_CIPHER_CTX_free(ctx);
59	}
60	
61	static void aes_decrypt(const uint8_t *key, const uint8_t *iv, const uint8_t *in, uint8_t *out, size_t len) {
62	    EVP_CIPHER_CTX *ctx = s_EVP_CIPHER_CTX_new();
63	    s_EVP_DecryptInit_ex(ctx, s_EVP_aes_128_cbc(), NULL, key, iv);
64	    s_EVP_CIPHER_CTX_set_padding(ctx, 0);
65	    int outlen;
66	    s_EVP_DecryptUpdate(ctx, out, &outlen, in, len);
67	    int outlen2;
68	    s_EVP_DecryptFinal_ex(ctx, out + outlen, &outlen2);
69	    s_EVP_CIPHER_CTX_free(ctx);
70	}
71	
72	static void hmac_sha1_avx_compute_golden(struct hmac_sha1_avx_data *d) {
73	    aes_encrypt(d->aes_key, d->aes_iv, d->plaintext, d->golden_ciphertext, DATA_SIZE);
74	    hmac_sha1_96(d->hmac_key, d->golden_ciphertext, DATA_SIZE, d->golden_mac);
75	}
76	
77	static int hmac_sha1_avx_init(struct test *test) {
78	    if (s_EVP_CIPHER_CTX_new && s_EVP_EncryptInit_ex && s_EVP_DecryptInit_ex && s_EVP_aes_128_cbc() && s_HMAC_CTX_new && s_EVP_sha1) {
79	        struct hmac_sha1_avx_data *d = (struct hmac_sha1_avx_data *)malloc(sizeof(*d));
80	        if (!d) return EXIT_SKIP;
81	
82	        memset_random(d->aes_key, AES_KEY_SIZE);
83	        memset_random(d->aes_iv, AES_IV_SIZE);
84	        memset_random(d->hmac_key, SHA1_KEY_SIZE);
85	        memset_random(d->plaintext, DATA_SIZE);
86	
87	        hmac_sha1_avx_compute_golden(d);
88	
89	        test->data = d;
90	        return EXIT_SUCCESS;
91	    } else {
92	        log_skip(TestResourceIssueSkipCategory, "OpenSSL library is not available or the current version is not supported");
93	        return EXIT_SKIP;
94	    }
95	}
96	
97	static int hmac_sha1_avx_run(struct test *test, int cpu) {
98	    struct hmac_sha1_avx_data *d = (struct hmac_sha1_avx_data *)test->data;
99	
100	    uint8_t *ciphertext = (uint8_t *)malloc(DATA_SIZE);
101	    uint8_t *decrypted = (uint8_t *)malloc(DATA_SIZE);
102	    uint8_t *mac = (uint8_t *)malloc(SHA1_96_DIGEST_SIZE);
103	
104	    TEST_LOOP(test, 256) {
105	        aes_encrypt(d->aes_key, d->aes_iv, d->plaintext, ciphertext, DATA_SIZE);
106	        memcmp_or_fail(ciphertext, d->golden_ciphertext, DATA_SIZE, "AES-128-CBC ciphertext mismatch (AVX)");
107	
108	        aes_decrypt(d->aes_key, d->aes_iv, ciphertext, decrypted, DATA_SIZE);
109	        memcmp_or_fail(decrypted, d->plaintext, DATA_SIZE, "AES-128-CBC decryption mismatch (AVX)");
