/**
 * @copyright
 * Copyright 2022 Intel Corporation.
 * SPDX-License-Identifier: Apache-2.0
 *
 * @test @b ipsec_aes128_cbc_hmac_sha1_avx
 * @parblock
 * This test encrypts random data using AES-128-CBC encryption and computes
 * an HMAC-SHA1-96 message authentication code (truncated to 12 bytes) on the
 * ciphertext via OpenSSL using the AVX optimized code path. It also decrypts 
 * the ciphertext and verifies that it matches the original plaintext. The 
 * ciphertext, MAC, and decrypted data are compared against pre-computed 
 * golden values on every iteration to detect silent data corruption.
 * @endparblock
 */

#include "sandstone.h"

#if SANDSTONE_SSL_BUILD
#include "sandstone_ssl.h"
#include <string.h>

#define DATA_SIZE             (1024u)
#define AES_KEY_SIZE          (16)
#define AES_IV_SIZE           (16)
#define SHA1_KEY_SIZE         (20)
#define SHA1_96_DIGEST_SIZE   (12)
#define SHA1_FULL_DIGEST_SIZE (20)

struct hmac_sha1_avx_data {
    uint8_t aes_key[AES_KEY_SIZE];
    uint8_t aes_iv[AES_IV_SIZE];
    uint8_t hmac_key[SHA1_KEY_SIZE];
    uint8_t plaintext[DATA_SIZE];
    uint8_t golden_ciphertext[DATA_SIZE];
    uint8_t golden_mac[SHA1_96_DIGEST_SIZE];
};

static void hmac_sha1_96(const uint8_t *key, const uint8_t *msg, size_t len, uint8_t *out) {
    HMAC_CTX *ctx = s_HMAC_CTX_new();
    s_HMAC_Init_ex(ctx, key, SHA1_KEY_SIZE, s_EVP_sha1(), NULL);
    s_HMAC_Update(ctx, msg, len);
    uint8_t full_mac[SHA1_FULL_DIGEST_SIZE];
    unsigned int outlen;
    s_HMAC_Final(ctx, full_mac, &outlen);
    s_HMAC_CTX_free(ctx);
    memcpy(out, full_mac, SHA1_96_DIGEST_SIZE);
}

static void aes_encrypt(const uint8_t *key, const uint8_t *iv, const uint8_t *in, uint8_t *out, size_t len) {
    EVP_CIPHER_CTX *ctx = s_EVP_CIPHER_CTX_new();
    s_EVP_EncryptInit_ex(ctx, s_EVP_aes_128_cbc(), NULL, key, iv);
    s_EVP_CIPHER_CTX_set_padding(ctx, 0);
    int outlen;
    s_EVP_EncryptUpdate(ctx, out, &outlen, in, len);
    int outlen2;
    s_EVP_EncryptFinal_ex(ctx, out + outlen, &outlen2);
    s_EVP_CIPHER_CTX_free(ctx);
}

static void aes_decrypt(const uint8_t *key, const uint8_t *iv, const uint8_t *in, uint8_t *out, size_t len) {
    EVP_CIPHER_CTX *ctx = s_EVP_CIPHER_CTX_new();
    s_EVP_DecryptInit_ex(ctx, s_EVP_aes_128_cbc(), NULL, key, iv);
    s_EVP_CIPHER_CTX_set_padding(ctx, 0);
    int outlen;
    s_EVP_DecryptUpdate(ctx, out, &outlen, in, len);
    int outlen2;
    s_EVP_DecryptFinal_ex(ctx, out + outlen, &outlen2);
    s_EVP_CIPHER_CTX_free(ctx);
}

static void hmac_sha1_avx_compute_golden(struct hmac_sha1_avx_data *d) {
    aes_encrypt(d->aes_key, d->aes_iv, d->plaintext, d->golden_ciphertext, DATA_SIZE);
    hmac_sha1_96(d->hmac_key, d->golden_ciphertext, DATA_SIZE, d->golden_mac);
}

static int hmac_sha1_avx_init(struct test *test) {
    if (s_EVP_CIPHER_CTX_new && s_EVP_EncryptInit_ex && s_EVP_DecryptInit_ex && s_EVP_aes_128_cbc() && s_HMAC_CTX_new && s_EVP_sha1) {
        struct hmac_sha1_avx_data *d = (struct hmac_sha1_avx_data *)malloc(sizeof(*d));
        if (!d) return EXIT_SKIP;

        memset_random(d->aes_key, AES_KEY_SIZE);
        memset_random(d->aes_iv, AES_IV_SIZE);
        memset_random(d->hmac_key, SHA1_KEY_SIZE);
        memset_random(d->plaintext, DATA_SIZE);

        hmac_sha1_avx_compute_golden(d);

        test->data = d;
        return EXIT_SUCCESS;
    } else {
        log_skip(TestResourceIssueSkipCategory, "OpenSSL library is not available or the current version is not supported");
        return EXIT_SKIP;
    }
}

static int hmac_sha1_avx_run(struct test *test, int cpu) {
    struct hmac_sha1_avx_data *d = (struct hmac_sha1_avx_data *)test->data;

    uint8_t *ciphertext = (uint8_t *)malloc(DATA_SIZE);
    uint8_t *decrypted = (uint8_t *)malloc(DATA_SIZE);
    uint8_t *mac = (uint8_t *)malloc(SHA1_96_DIGEST_SIZE);

    TEST_LOOP(test, 256) {
        aes_encrypt(d->aes_key, d->aes_iv, d->plaintext, ciphertext, DATA_SIZE);
        memcmp_or_fail(ciphertext, d->golden_ciphertext, DATA_SIZE, "AES-128-CBC ciphertext mismatch (AVX)");

        aes_decrypt(d->aes_key, d->aes_iv, ciphertext, decrypted, DATA_SIZE);
        memcmp_or_fail(decrypted, d->plaintext, DATA_SIZE, "AES-128-CBC decryption mismatch (AVX)");

        hmac_sha1_96(d->hmac_key, ciphertext, DATA_SIZE, mac);
        memcmp_or_fail(mac, d->golden_mac, SHA1_96_DIGEST_SIZE, "HMAC-SHA1-96 digest mismatch (AVX)");
    }

    free(ciphertext);
    free(decrypted);
    free(mac);
    return EXIT_SUCCESS;
}

static int hmac_sha1_avx_cleanup(struct test *test) {
    free(test->data);
    return EXIT_SUCCESS;
}

DECLARE_TEST(ipsec_aes128_cbc_hmac_sha1_avx, "Intel IPSEC AES128-CBC w/ HMAC_SHA1-96 AVX")
    .groups = DECLARE_TEST_GROUPS(&group_ipsec),
    .test_init = hmac_sha1_avx_init,
    .test_run = hmac_sha1_avx_run,
    .test_cleanup = hmac_sha1_avx_cleanup,
    .minimum_cpu = IPSEC_X86_GATE(cpu_haswell),
    .quality_level = TEST_QUALITY_PROD,
END_DECLARE_TEST

#else

static int hmac_sha1_avx_init(struct test *test) {
    log_skip(OsNotSupportedSkipCategory, "OpenSSL build is not enabled");
    return EXIT_SKIP;
}

static int hmac_sha1_avx_run(struct test *test, int cpu) {
    __builtin_unreachable();
}

DECLARE_TEST(ipsec_aes128_cbc_hmac_sha1_avx, "Intel IPSEC AES128-CBC w/ HMAC_SHA1-96 AVX")
    .groups = DECLARE_TEST_GROUPS(&group_ipsec),
    .test_init = hmac_sha1_avx_init,
    .test_run = hmac_sha1_avx_run,
    .minimum_cpu = IPSEC_X86_GATE(cpu_haswell),
    .quality_level = TEST_QUALITY_PROD,
END_DECLARE_TEST

#endif

