1	/*
2	 * Copyright 2022 Intel Corporation.
3	 * SPDX-License-Identifier: Apache-2.0
4	 */
5	
6	/*
7	 * This file is intended for constructs and functions intended for tests to
8	 * use.
9	 *
10	 *  PLEASE READ BEFORE EDITING:
11	 *     This is a clean file, meaning everything in it is properly unit tested
12	 *     Please do not add anything to this file unless it is unit tested.
13	 *     All unit tests should be put in framework/unit-tests/sandstone_test_utils_tests.cpp
14	 *
15	 */
16	
17	
18	#ifndef SANDSTONE_TEST_UTILS_H
19	#define SANDSTONE_TEST_UTILS_H
20	#include <sys/mman.h>
21	#include <cstdint>
22	#include <map>
23	
24	// These macros have been copied from sandstone_p.h because sandstone_p.h creates
25	// too many dependencies to get under unit-test.  Eventually we should refactor
26	// simple macros like this out of sandstone_p.h to  break these dependencies
27	#define ROUND_UP_TO(value, n)       (((value) + (n) - 1) & (~((n) - 1)))
28	#define ROUND_UP_TO_PAGE(value)     ROUND_UP_TO(value, 4096U)
29	
30	
31	/* ManagedCodeBuffer
32	 *
33	 * The purpose of this is to allocate, free and protect memory buffers
34	 * that are intended for self-modifying-code situations or times when
35	 * you want to use xbyak and lock down the address of a given code block
36	 *
37	 * In general the usage of this will look like:
38	 *    ManagedCodeBuffer code_buffer;
39	 *    if (code_buffer.allocate(size)){
40	 *        copy_or_assemble_code_to(code_buffer.ptr());
41	 *        code_buffer.set_executable();
42	 *    }
43	 *    // The code block will be freed in the destructor of the ManagedCodeBuffer
44	 *
45	 * You can also use allocate_at(address, size) to lock down an address that you want
46	 * for the code block but there are some restrictions imposed by the mmap call - namely
47	 * the address supplied must be page aligned.
48	 *
49	*/
50	class ManagedCodeBuffer {
51	    uint8_t * buffer_ptr{static_cast<uint8_t *>(MAP_FAILED)}; // nullptr is a valid address for mmap, MAP_FAILED is not
52	    size_t buffer_size{0};
53	public:
54	    ~ManagedCodeBuffer(){
55	        free_code_buffer();
56	    }
57	
58	    // Default constructor
59	    ManagedCodeBuffer() {}
60	
